// Real-weather presets (docs/research/environment_spec.md §10) for the ?wx=<id> QA hook: time + raw KSFO report +
// runway-configuration input, from data/sfo_env_presets.js (generated by tools/env/build_env_presets_js.py).
import { ENV_PRESETS, SNAPSHOT_TAF, SNAPSHOT_TAFS, SNAPSHOT_METARS } from '../../data/sfo_env_presets.js';
// SNAPSHOT_TAF: the KSFO TAF in force at the data/snapshot.js time (spec §3.4; NWS TAFSFO 231727Z via the IEM archive)
// SNAPSHOT_TAFS / SNAPSHOT_METARS: every TAF issued on 23 Sep up to the snapshot time and the KSFO reports of the 24 h
// before it (IEM archives, public domain): light mode Dawn / ?t= before the snapshot get the weather of that time
// (review truth2-7: the scene showed a clear default sky with no label)
export { ENV_PRESETS, SNAPSHOT_TAF, SNAPSHOT_TAFS, SNAPSHOT_METARS };
/** The latest snapshot TAF issued at or before t (ms): the forecast known at that time (I). */
export function snapshotTafAt(t) {
  let best = null; for (const x of SNAPSHOT_TAFS || []) if (Date.parse(x.issued) <= t && (!best || x.issued > best.issued)) best = x;
  return best;
}
export const presetById = (id) => ENV_PRESETS.find(p => p.id === id) || null;
/** The preset's runway configuration input in the EnvState runway shape. */
export function presetRunway(p) {
  const r = p && p.runway_config_input; if (!r) return null;
  return { arr: { ...r.arr }, dep: (r.dep || []).slice(), source: 'preset input (' + p.id + '): ' + (r.note || ''), tag: 'I' };
}
